import json
from pathlib import Path

STATE_PATH = "/Users/dm/dev/dev/個人開発/HarnessHub/.worktrees/task-20260724-203623-wt-8/eval-log/dev-graph/live-trial-fixtures/system-spec-pr72-r5/system-spec/spec-state.json"
