GOAL_SPEC_CATEGORIES = ["database","auth","ui-ux","security","infrastructure","backend","frontend","maintenance-ops"]
PLACEHOLDER_PATTERNS = ["-", "n/a", "対象外", ""]

cat_ids = [c["id"] for c in data["categories"]]
qa_ids = {e["id"] for e in data.get("qa_log", []) if isinstance(e, dict)}
approval_ids = {e["id"] for e in data.get("approval_log", []) if isinstance(e, dict)}
