            unresolved.append(f"{cat}.{pf}")
print(f"未収集セル数: {len(unresolved)}")
if unresolved:
    for c in unresolved:
        print(f"  未収集: {c}")
else:
    print("  未収集なし")

print()
print("=== (b) 対象外理由の妥当性 ===")
PLACEHOLDER_EXACT = {"-", "n/a", "対象外", "", "N/A"}
reason_issues = []
reason_ok = []
for cat in cat_ids:
    row = matrix.get(cat, {})
    for pf in CANONICAL_PLATFORMS:
        cell = row.get(pf, {})
        if cell.get("state") == "対象外":
            reason = cell.get("reason", "")
            approval_ref = cell.get("approval_ref", "")
            if not reason and not approval_ref:
                reason_issues.append((cat, pf, "reason も approval_ref も空"))
            elif reason and reason.strip().lower() in PLACEHOLDER_EXACT:
                reason_issues.append((cat, pf, f"理由がplaceholder: {reason!r}"))
            elif reason and reason.strip() == cat:
                reason_issues.append((cat, pf, f"理由がカテゴリ同語反復: {reason!r}"))
            elif reason and len(reason.strip()) < 5:
                reason_issues.append((cat, pf, f"理由が短すぎる (記号のみ疑い): {reason!r}"))
            else:
                reason_ok.append((cat, pf, reason[:50]))
print(f"対象外セル数: {len(reason_ok) + len(reason_issues)}, 理由要改善: {len(reason_issues)}")
if reason_issues:
    for cat, pf, msg in reason_issues:
        print(f"  理由要改善: {cat}.{pf} -> {msg}")
else:
    print("  全対象外セルに具体的理由あり")

print()
print("=== (b) approval_ref の実在確認 ===")
for cat in cat_ids:
    row = matrix.get(cat, {})
    for pf in CANONICAL_PLATFORMS:
        cell = row.get(pf, {})
        if cell.get("state") == "対象外":
            ar = cell.get("approval_ref")
            if ar and ar not in approval_ids:
                print(f"  dangling approval_ref: {cat}.{pf} -> {ar}")
print("  approval_ref の実在確認完了")
print(f"  approval_log ids: {approval_ids}")

print()
print("=== (c) 確定 qa_ref トレーサビリティ ===")
qa_ref_issues = []
qa_ref_ok = []
for cat in cat_ids:
